import{_ as d,a0 as s,w as a,s as n,ao as f,I as o,x as i,a1 as r,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"提高 LibreOffice 生產力的技巧 | LCTT x X-CMD","titleTemplate":false,"description":"提高 LibreOffice 生產力的技巧 | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"提高 LibreOffice 生產力的技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"提高 LibreOffice 生產力的技巧 | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20210922 My favorite LibreOffice productivity tips","title":"提高 LibreOffice 生產力的技巧","tag":"202302","desc":""},"relativePath":"202302/20210922 My favorite LibreOffice productivity tips.md","filePath":"[post].md"}'),u={name:"202302/20210922 My favorite LibreOffice productivity tips.md"};function p(b,e,O,m,c,L){const t=s("Link");return a(),n("div",null,[e[21]||(e[21]=f('<h1 id="提高-libreoffice-生產力的技巧" tabindex="-1">提高 LibreOffice 生產力的技巧 <a class="header-anchor" href="#提高-libreoffice-生產力的技巧" aria-label="Permalink to “提高 LibreOffice 生產力的技巧”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/11/161923gks1dsldq7dd1z67.jpg" alt=""></p><blockquote><p>今天我將和大家分享一些 LibreOffice 的鍵盤快捷鍵和排版技巧，希望能夠幫你省下寶貴的時間。</p></blockquote><p>LibreOffice 是我首選的生產力應用程序。它是向教育工作者和學生推薦 Linux 發行版的最有力理由之一，無論是 PK-12 還是高等教育。新的學年快到了，我想也是時候推薦一些 LibreOffice 快捷方式和技巧，它們可以為你節省寶貴的時間。</p><h3 id="使用鍵盤快捷鍵讓你工作更快捷" tabindex="-1">使用鍵盤快捷鍵讓你工作更快捷 <a class="header-anchor" href="#使用鍵盤快捷鍵讓你工作更快捷" aria-label="Permalink to “使用鍵盤快捷鍵讓你工作更快捷”">​</a></h3><p>我平時經常使用鍵盤快捷鍵，以下是適用於所有 LibreOffice 應用程序的最常見的快捷鍵</p><ul><li><code>Ctrl+N</code> — 創建新文檔</li><li><code>Ctrl+O</code> — 打開一個文檔</li><li><code>Ctrl+S</code> — 保存文檔</li><li><code>Ctrl+Shift+S</code> — 另存為</li><li><code>Ctrl+P</code> — 打印文檔</li></ul><p>這些是僅適用於 LibreOffice Writer 的快捷鍵：</p><ul><li><code>Home</code> — 移動到當前行的初始位置</li><li><code>End</code> — 移動至當前行的結尾位置</li><li><code>Ctrl+Home</code> — 將光標移動到文檔的初始位置</li><li><code>Ctrl+End</code> — 將光標移動到文檔的結尾位置</li><li><code>Ctrl+A</code> — 全選</li><li><code>Ctrl+D</code> — 雙下劃線</li><li><code>Ctrl+E</code> — 居中</li><li><code>Ctrl+H</code> — 查找並替換</li><li><code>Ctrl+L</code> — 左對齊</li><li><code>Ctrl+R</code> — 右對齊</li></ul><p>功能鍵也大有用處：</p><ul><li><code>F2</code> — 打開公式欄</li><li><code>F3</code> — 自動補完</li><li><code>F5</code> — 打開導航器</li><li><code>F7</code> — 打開拼寫和語法</li><li><code>F11</code> — 打開格式和排版</li><li><code>Shift+F11</code> — 創建新樣式</li></ul><h3 id="文檔格式" tabindex="-1">文檔格式 <a class="header-anchor" href="#文檔格式" aria-label="Permalink to “文檔格式”">​</a></h3><p>文檔格式有很多種，LibreOffice 支持其中很多文檔格式。默認情況下，LibreOffice 將文檔保存為 <ruby>開放文檔格式<rt>Open Document Format</rt></ruby>（ODF），這是一種開源標準，將樣式表和數據存儲在 ZIP 容器中，文本文檔標記為 ODT，電子表格標記為 ODS，演示文稿標記為 ODP。它是一種靈活的格式，由 LibreOffice 社區和文檔基金會維護。</p><p>ODF 是默認啓用的，因此你無需執行任何操作即可讓 LibreOffice 使用這種格式。</p>',14)),o("p",null,[e[1]||(e[1]=i("另一種文檔開放規範是微軟的 ",-1)),r(t,{href:"https://www.iso.org/standard/71691.html"},{default:l(()=>[...e[0]||(e[0]=[i("Office Open XML（OOXML）格式",-1)])]),_:1}),e[2]||(e[2]=i("。它是一個 ISO 標準，並得到所有主要辦公解決方案的良好支持。",-1))]),e[22]||(e[22]=f('<p>如果你與使用微軟 Office 的人一起工作（它本身不是開源的，但它確實使用開放的 OOXML 格式），那麼他們肯定習慣於 DOCX、XLSX 和 PPTX 格式，並且可能無法打開 ODT、ODS 或 ODP 文件。你可以通過在 LibreOffice 中將 OOXML 設置為默認格式來避免很多混亂。</p><p>將 OOXML 設置為你的首選格式：</p><ol><li>單擊 “<ruby>工具<rt>Tools</rt></ruby>” 菜單並選擇菜單底部的 “<ruby>選項<rt>Options</rt></ruby>”。</li><li>在 “<ruby>選項<rt>Options</rt></ruby>” 窗口中，單擊左側面板中的 “<ruby>加載/保存<rt>Load/Save</rt></ruby>” 類別，然後選擇 “<ruby>常規<rt>General</rt></ruby>”。<br><img src="https://opensource.com/sites/default/files/uploads/libreoffice-panel.jpg" alt="LibreOffice設置面板" title="LibreOffice settings panel"></li><li>導航到 “<ruby>默認文件格式和 ODF 設置<rt>Default File Format and ODF Settings</rt></ruby>” 部分。</li><li>在 “<ruby>文檔類型<rt>Document type</rt></ruby>” 選擇 “<ruby>文本文檔<rt>Text document</rt></ruby>”，並在 “<ruby>始終另存為<rt>Always save as</rt></ruby>” 下拉列表選擇 “Open XML (Transitional) (*.docx) ”。</li><li>點擊 “<ruby>應用<rt>Apply</rt></ruby>” 然後點擊 “<ruby>確定<rt>OK</rt></ruby>”。</li><li>取消選擇 “<ruby>未以 ODF 或默認格式保存時發出警告<rt>Warn when not saving in ODF or default format </rt></ruby>” 以避免在保存時出現確認對話框。 <img src="https://opensource.com/sites/default/files/uploads/libreoffice-save-format.jpg" alt="LibreOffice 保存格式" title="LibreOffice save formats"></li></ol><p>按照相同的邏輯重複，重複相同的過程用於 XLSX 和 PPTX 文檔。</p><h3 id="讓辦公更自由" tabindex="-1">讓辦公更自由 <a class="header-anchor" href="#讓辦公更自由" aria-label="Permalink to “讓辦公更自由”">​</a></h3>',5)),o("p",null,[e[4]||(e[4]=i("LibreOffice 項目由蓬勃發展的用户和開發人員社區與文檔基金會共同管理。這包括工程指導委員會、董事會、獨立開發人員、設計師和翻譯人員等。這些團隊始終歡迎各位的貢獻，因此如果你渴望參與一個超讚的開源項目，請不要猶豫 ",-1)),r(t,{href:"https://www.libreoffice.org/community/get-involved/"},{default:l(()=>[...e[3]||(e[3]=[i("參與進來",-1)])]),_:1}),e[5]||(e[5]=i("。",-1))]),e[23]||(e[23]=o("hr",null,null,-1)),o("p",null,[e[7]||(e[7]=i("via: ",-1)),r(t,{href:"https://opensource.com/article/21/9/libreoffice-tips"},{default:l(()=>[...e[6]||(e[6]=[i("https://opensource.com/article/21/9/libreoffice-tips",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=i("作者：",-1)),r(t,{href:"https://opensource.com/users/don-watkins"},{default:l(()=>[...e[8]||(e[8]=[i("Don Watkins",-1)])]),_:1}),e[13]||(e[13]=i(" 選題：",-1)),r(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[9]||(e[9]=[i("lujun9972",-1)])]),_:1}),e[14]||(e[14]=i(" 譯者：",-1)),r(t,{href:"https://github.com/XiaotingHuang22"},{default:l(()=>[...e[10]||(e[10]=[i("XiaotingHuang22",-1)])]),_:1}),e[15]||(e[15]=i(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:l(()=>[...e[11]||(e[11]=[i("wxy",-1)])]),_:1})]),o("p",null,[e[18]||(e[18]=i("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[16]||(e[16]=[i("LCTT",-1)])]),_:1}),e[19]||(e[19]=i(" 原創編譯，",-1)),r(t,{href:"https://linux.cn/"},{default:l(()=>[...e[17]||(e[17]=[i("Linux中國",-1)])]),_:1}),e[20]||(e[20]=i(" 榮譽推出",-1))])])}const g=d(u,[["render",p]]);export{C as __pageData,g as default};
